public class Identical {
    private int total;

    public void countUp(int[] values) {
        for (int value : values) {
            {
                total += value;
                total += value * 2;
                total += value * 3;
                total += value * 4;
                total += value * 5;
                total += value * 6;
                total += value * 7;
                total += value * 8;
                total += value * 9;
                total += value * 10;
                total += value * 11;
                total += value * 12;
                total += value * 13;
                total += value * 14;
                total += value * 15;
                total += value * 16;
            }
        }
    }

    public void countWhile(int[] values) {
        int index = 0;
        while (index < values.length) {
            int value = values[index];
            index++;
            {
                total += value;
                total += value * 2;
                total += value * 3;
                total += value * 4;
                total += value * 5;
                total += value * 6;
                total += value * 7;
                total += value * 8;
                total += value * 9;
                total += value * 10;
                total += value * 11;
                total += value * 12;
                total += value * 13;
                total += value * 14;
                total += value * 15;
                total += value * 16;
            }
        }
    }
}
